const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const S = input[1];

let prefix = 0;
let answer = 0;
const counts = new Map([[0, 1]]);

for (let i = 0; i < N; i++) {
  prefix += input[i + 2];
  answer += counts.get(prefix - S) || 0;
  counts.set(prefix, (counts.get(prefix) || 0) + 1);
}

console.log(answer);
